export const SevenColours: Story = {
  render: () => (
    <SwatchesWithState
      variants={[
        makeVariant('raspberry', 'Raspberry'),
        makeVariant('ivory', 'Ivory'),
        makeVariant('navy', 'Navy'),
        makeVariant('black', 'Black'),
        makeVariant('sage', 'Sage'),
        makeVariant('coral', 'Coral'),
        makeVariant('lilac', 'Lilac'),
      ]}
      initialValue="raspberry"
    />
  ),
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const nextBtn = canvas.getByRole('button', { name: 'Next colours' });
    const prevBtn = canvas.getByRole('button', { name: 'Previous colours' });

    // Page 0: first 4 swatches visible; prev is at boundary (disabled).
    await expect(canvas.queryAllByRole('radio')).toHaveLength(4);
    await expect(prevBtn).toBeDisabled();
    await expect(nextBtn).toBeEnabled();

    // Advance to page 1.
    await userEvent.click(nextBtn);

    // Page 1: remaining 3 swatches visible; next is now at boundary (disabled).
    await expect(canvas.queryAllByRole('radio')).toHaveLength(3);
    await expect(canvas.getByRole('radio', { name: 'Sage' })).toBeVisible();
    await expect(canvas.getByRole('radio', { name: 'Coral' })).toBeVisible();
    await expect(canvas.getByRole('radio', { name: 'Lilac' })).toBeVisible();
    await expect(nextBtn).toBeDisabled();
    await expect(prevBtn).toBeEnabled();
  },
};

